.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
d<-read.csv('outputs/stage6_foxp2_brain_mvp_nfe_aligned.csv');p<-nrow(d);R<-matrix(readBin('work/stage6_foxp2_brain_mvp_nfe_ld.bin','double',n=p*p,size=8,endian='little'),p,p);dimnames(R)<-list(d$rs,d$rs);stopifnot(min(eigen(R,symmetric=TRUE,only.values=TRUE)$values)> -1e-8)
diag<-list(); pairs<-list();members<-list();fits<-list();for(nbrain in c(757,983)){for(t in c('brain','mvp')){nm<-paste(t,nbrain,sep='_');z<-if(t=='brain')d$brain_z_anchor else d$mvp_z_anchor;n<-if(t=='brain')nbrain else 253769;names(z)<-d$rs;lambda<-estimate_s_rss(z,R,n=n);set.seed(42);f<-susie_rss(z=z,R=R,n=n,L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[nm]]<-f;diag[[length(diag)+1]]<-data.frame(trait=t,brain_n=nbrain,working_n=n,n_variants=p,lambda=lambda,converged=f$converged,iterations=f$niter,n_sets=length(f$sets$cs),max_pip=max(f$pip));if(length(f$sets$cs))for(k in seq_along(f$sets$cs)){ii<-f$sets$cs[[k]];members[[length(members)+1]]<-data.frame(trait=t,brain_n=nbrain,component=f$sets$cs_index[k],rs=d$rs[ii],pip=f$pip[ii])};cat(nm,'sets',length(f$sets$cs),'lambda',lambda,'converged',f$converged,'\n');flush.console()};a<-fits[[paste0('brain_',nbrain)]];b<-fits[[paste0('mvp_',nbrain)]];if(length(a$sets$cs)&&length(b$sets$cs))for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(a,b,p1=1e-4,p2=1e-4,p12=p12)$summary);x$brain_n<-nbrain;x$p12<-p12;pairs[[length(pairs)+1]]<-x}}
write.csv(do.call(rbind,diag),'outputs/stage6_foxp2_brain_mvp_pair_diagnostics.csv',row.names=FALSE);if(length(members))write.csv(do.call(rbind,members),'outputs/stage6_foxp2_brain_mvp_pair_members.csv',row.names=FALSE);if(length(pairs))write.csv(do.call(rbind,pairs),'outputs/stage6_foxp2_brain_mvp_pair_coloc.csv',row.names=FALSE);saveRDS(fits,'work/stage6_foxp2_brain_mvp_pair_fits.rds')
